//! Generated art for the `udtk` splash screen. **Do not edit by hand.**
//!
//! Regenerate with `make_splash.py` (docs/unidtkascii.md §5):
//!
//!     make_splash.py --repo <UniDTK repo root>
//!
//! Source of the shape: procedural emblem built by `unidtk_emblem.py`
//! (hexagon R=84 rc=20 on a 200x200 dot grid, threshold 0.35).
//! Source of the shade: Serpiente alquimica (ouroboros, Byzantine alchemical manuscript) (1478), https://commons.wikimedia.org/wiki/File:Serpiente_alquimica.jpg -- Public domain (PD-old), SHA-256 `af419b614c4bc60d`.
//! The shade byte is a multiplier on the serpent's brand colour: 128 == neutral,
//! `shade` applies to cells the runtime paints as serpent body only. Empty
//! braille cells are plain spaces (no invisible characters).

/// Dot-space mapping of a trimmed art block. `scale_*` are generator dot units
/// per braille dot (square, so they are equal); `top_off` is the number of cell
/// rows the trim removed from the top of the untrimmed block.
pub struct Geo {
    /// Character columns of the block (== every line's length).
    pub cols: usize,
    /// Blank cell rows trimmed from the top.
    pub top_off: usize,
    /// Generator dot units per braille dot, horizontally / vertically.
    pub scale_x: f32,
    pub scale_y: f32,
    /// Per-cell shade, row after row (`cols` bytes per row, 128 == neutral).
    pub shade: &'static [u8],
}

/// Saturn in generator dot coordinates: centre x, centre y, radius.
pub const SPHERE: (f32, f32, f32) = (100.0, 100.0, 30.0);
/// Ring system semi-axes (outer / middle / inner) and the axis tilt, degrees.
pub const RINGS: [(f32, f32); 3] = [(52.0, 13.8), (45.0, 12.0), (38.0, 10.1)];
#[allow(dead_code)]
pub const TILT_DEG: f32 = 26.7;

